 const lineRows=id=>db.prepare('SELECT * FROM pink_pack_purchase_lines WHERE purchase_id=? ORDER BY id').all(id);
 function reserved(id,location,exclude=0){return sum(`SELECT SUM(l.quantity) v FROM pink_pack_reservation_lines l JOIN pink_pack_reservations r ON r.id=l.reservation_id WHERE l.material_id=? AND r.status='Reserved' AND r.id!=?${location===undefined?'':' AND COALESCE(l.location_id,0)=?'}`,id,exclude,...(location===undefined?[]:[Number(location)||0]))}
