 function financial(p){const tx=db.prepare("SELECT t.*,f.verification_status,f.accounting_status FROM pink_fx_transactions t LEFT JOIN finance_entries f ON f.id=t.finance_entry_id WHERE t.workflow IN ('packaging_purchase','packaging_refund') AND t.record_id=? ORDER BY t.id DESC").all(p.id),allocations=db.prepare('SELECT * FROM pink_salt_supplier_packaging_allocations WHERE purchase_id=? ORDER BY id DESC').all(p.id);const credit=round(sum('SELECT SUM(amount_krw) v FROM pink_pack_credits WHERE purchase_id=? AND status=\'Active\'',p.id)),refunded=round(sum("SELECT SUM(allocation_krw) v FROM pink_fx_transactions WHERE workflow='packaging_refund' AND record_id=? AND status='Active'",p.id));const advance=round(allocations.filter(x=>x.status==='Active').reduce((n,x)=>n+x.amount_krw,0)),paid=round(tx.filter(x=>x.workflow==='packaging_purchase'&&x.status==='Active').reduce((n,x)=>n+x.allocation_krw,0)),verified=round(tx.filter(x=>x.workflow==='packaging_purchase'&&x.status==='Active'&&['Verified / Correct','Verified'].includes(x.verification_status)).reduce((n,x)=>n+x.allocation_krw,0));return {credit_krw:credit,refunded_krw:refunded,credit_balance_krw:Math.max(0,round(credit+advance+paid-p.total_krw-refunded)),transactions:tx,allocations,advance_krw:advance,paid_krw:paid,verified_paid_krw:verified,outstanding_krw:Math.max(0,round(p.total_krw-credit-advance-paid+refunded)),outstanding_invoice:Math.max(0,round((p.total_krw-credit-advance-paid+refunded)/p.recognition_rate))}}
 const numbered=(prefix,t)=>`${prefix}-${new Date().getFullYear()}-${String(Number(db.prepare(`SELECT COALESCE(MAX(id),0)+1 n FROM ${t}`).get().n)).padStart(6,'0')}`;
