  const u=json(b.units??old?.units_json);if(!Array.isArray(u)||u.some(x=>!text(x.unit)||!(Number(x.conversion)>0)||!Number.isFinite(Number(x.conversion))))fail('Unit conversions must be positive.');for(const entry of u)entry.conversion=D.number(D.fixed(entry.conversion));if(new Set(u.map(x=>text(x.unit))).size!==u.length)fail('Purchase units must be unique.');const reorder=Number(b.reorder_level??old?.reorder_level??0);if(!Number.isFinite(reorder)||reorder<0)fail('Reorder level cannot be negative.');
