 function approvePurchase(req,id){permission(req,'purchases');const p=purchase(id,guard(req));if(!['Draft','Pending Approval'].includes(p.status))fail('Purchase is no longer awaiting approval.',409);supplier(p.supplier_id,p.business_unit_id);db.prepare("UPDATE pink_pack_purchases SET status='Approved',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(id);history(req,'pink_pack_purchase',id,'Approved',p,purchase(id,p.business_unit_id));return {id,status:'Approved'}}
