 route('get','/stock',['inventory','purchases','finance'],req=>{const bu=guard(req),pg=page(req),q='%'+text(req.query.search)+'%',sql=`SELECT p.id,p.sku,p.name,p.name_ko,p.category,p.unit,p.reorder_level,m.location_id,COALESCE(l.warehouse,'Unassigned legacy location') warehouse,COALESCE(SUM(m.quantity),0) on_hand,COALESCE(SUM(m.quarantine_quantity),0) quarantined,COALESCE((SELECT SUM(rl.quantity) FROM pink_pack_reservation_lines rl JOIN pink_pack_reservations rr ON rr.id=rl.reservation_id WHERE rl.material_id=p.id AND COALESCE(rl.location_id,0)=COALESCE(m.location_id,0) AND rr.status='Reserved'),0) reserved,COALESCE(SUM(m.quantity),0)-COALESCE((SELECT SUM(rl.quantity) FROM pink_pack_reservation_lines rl JOIN pink_pack_reservations rr ON rr.id=rl.reservation_id WHERE rl.material_id=p.id AND COALESCE(rl.location_id,0)=COALESCE(m.location_id,0) AND rr.status='Reserved'),0) available FROM pink_salt_packaging_items p LEFT JOIN pink_salt_packaging_movements m ON m.packaging_item_id=p.id AND COALESCE(m.status,'Active')!='Voided' LEFT JOIN pink_salt_storage_locations l ON l.id=m.location_id WHERE p.business_unit_id=? AND (p.name LIKE ? OR p.sku LIKE ? OR p.name_ko LIKE ?) GROUP BY p.id,m.location_id ${req.query.filter==='low'?'HAVING p.reorder_level>0 AND COALESCE(SUM(m.quantity),0)<=p.reorder_level':''}`,args=[bu,q,q,q];return {...pg,total:sum(`SELECT COUNT(*) v FROM (${sql})`,...args),rows:db.prepare(sql+' ORDER BY p.name,m.location_id LIMIT ? OFFSET ?').all(...args,pg.page_size,(pg.page-1)*pg.page_size)}});
