 route('get','/production-preview',['inventory','purchases'],req=>{const bu=guard(req),outputs=json(req.query.outputs),needed=new Map();if(!Array.isArray(outputs)||outputs.length>100)fail('Invalid production outputs.');for(const o of outputs){const product=db.prepare('SELECT * FROM pink_salt_products WHERE id=? AND business_unit_id=? AND active=1').get(Number(o.product_id),bu);if(!product||!(Number(o.quantity_units)>0))continue;for(const l of db.prepare('SELECT * FROM pink_salt_bom_lines WHERE product_id=?').all(product.id))needed.set(l.packaging_item_id,(needed.get(l.packaging_item_id)||0)+l.quantity_per_unit*Number(o.quantity_units))}return {requirements:[...needed].map(([id,quantity])=>{const m=material(id,bu);return {material_id:id,sku:m.sku,name:m.name,name_ko:m.name_ko,unit:m.unit,expected_quantity:quantity,on_hand:available(id),physical_on_hand:balance(id),reserved:reserved(id),unit_cost_krw:m.last_unit_cost_krw}})}});
