 function consumeProduction(req,{material_id,quantity,production_date,batch_id,batch_no,cost,movement_type='Production Consumption',reason=''}){const bu=guard(req),m=material(material_id,bu);let left=quantity;const locations=db.prepare("SELECT location_id,SUM(quantity) quantity FROM pink_salt_packaging_movements WHERE packaging_item_id=? AND COALESCE(status,'Active')!='Voided' GROUP BY location_id HAVING SUM(quantity)>0 ORDER BY location_id IS NULL,location_id").all(material_id).filter(l=>!req.packaging_reservation_locations||!Object.hasOwn(req.packaging_reservation_locations,material_id)||l.location_id===req.packaging_reservation_locations[material_id]);if(available(material_id,undefined,Number(req.body.packaging_reservation_id||0))<quantity-0.000001)fail('Insufficient material stock.',409);const ids=[];for(const l of locations){const take=Math.min(left,available(material_id,l.location_id,Number(req.body.packaging_reservation_id||0)));if(take<=0)continue;ids.push(move(req,{packaging_item_id:material_id,movement_date:production_date,movement_type,quantity:-take,unit_cost_krw:cost,reference_type:'Production',reference_id:batch_id,reference:batch_no,notes:reason||'Confirmed production packaging consumption',location_id:l.location_id}));left-=take;if(left<0.000001)break}if(left>0.000001)fail('Insufficient material stock.',409);history(req,'pink_pack_production',batch_id,'Production Consumption',{}, {material_id,quantity,cost,movement_ids:ids,bom_snapshot:db.prepare('SELECT * FROM pink_salt_production_outputs WHERE production_batch_id=?').all(batch_id)});return ids}
 function productionReturn(req,b){permission(req,'inventory','edit');reasonRequired(b);const bu=guard(req),batch=db.prepare("SELECT * FROM pink_salt_production_batches WHERE id=? AND business_unit_id=? AND status='Completed'").get(Number(b.batch_id),bu);if(!batch)fail('Select a completed production batch.');const used=db.prepare('SELECT * FROM pink_salt_production_packaging WHERE production_batch_id=? AND packaging_item_id=?').get(batch.id,Number(b.material_id)),q=D.number(D.fixed(b.quantity)),previous=sum('SELECT SUM(quantity) v FROM pink_pack_production_returns WHERE batch_id=? AND material_id=?',batch.id,Number(b.material_id));if(!used||!(q>0)||q>Number(used.actual_used_quantity??used.quantity_used)-previous+0.000001)fail('Return exceeds unreturned useful packaging consumption.',409);const d=date(b.movement_date),loc=location(req,b.location_id),m=material(used.packaging_item_id,bu),value=D.valuationMoney(q,used.unit_cost_krw),out=db.prepare('SELECT * FROM pink_salt_production_outputs WHERE production_batch_id=?').all(batch.id),weights=out.map(o=>{const snap=json(used.bom_snapshot_json).find(x=>x.product_id===o.product_id),line=snap?.bom?.find(x=>x.packaging_item_id===m.id);return line?D.multiply(line.quantity_per_unit,snap.quantity):0}),weight=D.total(weights);if(!weight)fail('Original packaging BOM trace is missing. Use a controlled batch correction.',409);const id=insert('pink_pack_production_returns',{business_unit_id:bu,batch_id:batch.id,material_id:m.id,quantity:q,reason:b.reason,movement_date:d,created_by:req.user.id});let left=value,finishedValue=0,expenseValue=0;for(let i=0;i<out.length;i++){const o=out[i],allocation=i===out.length-1?left:D.proportionMoney(value,weights[i],weight);left=D.total([left,-allocation]);if(!allocation)continue;const current=sum('SELECT SUM(quantity_units) v FROM pink_salt_finished_stock_movements WHERE product_id=?',o.product_id),retained=Math.min(o.quantity_units,Math.max(0,current)),toStock=D.proportionMoney(allocation,retained,o.quantity_units);finishedValue=D.total([finishedValue,toStock]);expenseValue=D.total([expenseValue,allocation,-toStock]);insert('pink_pack_finished_cost_adjustments',{return_id:id,batch_id:batch.id,product_id:o.product_id,amount_krw:allocation})}const prior=balance(m.id),newCost=(prior*m.last_unit_cost_krw+value)/(prior+q);move(req,{packaging_item_id:m.id,movement_date:d,movement_type:'Production Return',quantity:q,unit_cost_krw:used.unit_cost_krw,reference_type:'Production',reference_id:batch.id,reference:batch.batch_no,location_id:loc.id,notes:b.reason});db.prepare('UPDATE pink_salt_packaging_items SET last_unit_cost_krw=? WHERE id=?').run(newCost,m.id);const lines=[jl('PINK_SALT_PACKAGING_INVENTORY',value,0)];if(finishedValue)lines.push(jl('PINK_SALT_FINISHED_INVENTORY',0,finishedValue));if(expenseValue)lines.push(jl('GENERAL_EXPENSE',0,expenseValue,{memo:'Return of packaging previously charged to issued finished goods'}));const jid=journal(req,{business_unit_id:bu,purchase_no:batch.batch_no},'Pink Packaging Production Return',id,d,lines);db.prepare('UPDATE pink_pack_production_returns SET journal_id=? WHERE id=?').run(jid,id);history(req,'pink_pack_production',batch.id,'Unused packaging returned',{}, {return_id:id,material_id:m.id,quantity:q,value_krw:value,journal_id:jid,reason:b.reason});return {id,journal_id:jid}}
 route('get','/production-returns',['inventory'],req=>({batches:db.prepare("SELECT id,batch_no,production_date FROM pink_salt_production_batches WHERE business_unit_id=? AND status='Completed' ORDER BY id DESC LIMIT 100").all(guard(req)),usage:db.prepare("SELECT p.*,b.batch_no,m.sku,m.name,m.name_ko,m.unit,COALESCE((SELECT SUM(quantity) FROM pink_pack_production_returns r WHERE r.batch_id=b.id AND r.material_id=p.packaging_item_id),0) returned FROM pink_salt_production_packaging p JOIN pink_salt_production_batches b ON b.id=p.production_batch_id JOIN pink_salt_packaging_items m ON m.id=p.packaging_item_id WHERE b.business_unit_id=? AND b.status='Completed' ORDER BY b.id DESC LIMIT 1000").all(guard(req))}));
