 function externalCost(req,id,b){permission(req,'finance');reasonRequired(b);const bu=guard(req),p=purchase(id,bu),s=db.prepare('SELECT * FROM pink_salt_suppliers WHERE id=? AND business_unit_id=? AND active=1').get(Number(b.supplier_id),bu);if(!s||!p.invoice_journal_id||!['Approved','Closed'].includes(p.status))fail('Select an existing active cost supplier and recognized purchase.');const currency=text(b.currency)||'KRW',rate=currency==='KRW'?1:D.number(D.fixed(b.recognition_rate)),amount=D.number(D.fixed(b.amount)),ref=text(b.invoice_reference),d=date(b.cost_date),treatment=b.treatment;if(!allowedCurrencies.has(currency)||!(rate>0)||!(amount>0)||!ref||!['capitalizable','operating','recoverable_tax'].includes(treatment))fail('Enter valid third-party invoice details and classification.');const lines=lineRows(id);if(treatment==='capitalizable'&&lines.some(l=>l.base_quantity-l.cancelled_quantity-received(l.id).accepted>0.000001))fail('Finalize material receipts before allocating the final third-party acquisition invoice.',409);const allocations=[],value=D.convertMoney(amount,rate),meta={entity_type:'Pink Salt Supplier',entity_id:s.id,original_currency:currency,original_amount:amount,fx_rate:rate},post=[];if(treatment==='capitalizable'){const weight=D.total(lines.map(l=>l.inventory_krw));let left=value;for(let i=0;i<lines.length;i++){const l=lines[i],allocation=i===lines.length-1?left:D.proportionMoney(value,l.inventory_krw,weight);left=D.total([left,-allocation]);const m=material(l.material_id,bu),stock=balance(m.id),ordered=l.base_quantity-l.cancelled_quantity,retained=Math.min(ordered,Math.max(0,stock)),held=D.proportionMoney(allocation,retained,ordered),issued=D.total([allocation,-held]);if(held){post.push(jl('PINK_SALT_PACKAGING_INVENTORY',held,0,{entity_type:'Packaging Material',entity_id:m.id,memo:l.snapshot_json}));allocations.push({material_id:m.id,stock_quantity:stock,inventory_value:held});db.prepare('UPDATE pink_salt_packaging_items SET last_unit_cost_krw=? WHERE id=?').run((stock*m.last_unit_cost_krw+held)/stock,m.id)}if(issued)post.push(jl('GENERAL_EXPENSE',issued,0,{memo:'Acquisition cost for previously issued packaging'}));move(req,{packaging_item_id:m.id,movement_date:d,movement_type:'Acquisition Cost Allocation',quantity:0,unit_cost_krw:ordered?allocation/ordered:0,reference_type:'Packaging External Cost',reference_id:id,reference:ref,purchase_id:id,notes:b.reason})}}else if(treatment==='recoverable_tax'){const a=db.prepare("SELECT id FROM accounting_accounts WHERE id=? AND active=1 AND account_type='Asset' AND (lower(subtype) LIKE '%tax%' OR lower(subtype) LIKE '%vat%') AND id NOT IN (SELECT ledger_account_id FROM accounting_payment_accounts WHERE ledger_account_id IS NOT NULL)").get(Number(b.tax_account_id));if(!a)fail('Select an existing asset ledger for recoverable tax.');post.push({account_id:a.id,debit_krw:value,credit_krw:0})}else post.push(jl('GENERAL_EXPENSE',value,0));post.push(jl('ACCOUNTS_PAYABLE',0,value,meta));const cid=insert('pink_pack_external_costs',{business_unit_id:bu,purchase_id:id,supplier_id:s.id,invoice_reference:ref,cost_date:d,currency,amount,recognition_rate:rate,amount_krw:value,treatment,allocation_json:JSON.stringify(allocations),reason:b.reason,created_by:req.user.id}),jid=journal(req,p,'Pink Packaging External Cost',cid,d,post);db.prepare('UPDATE pink_pack_external_costs SET journal_id=? WHERE id=?').run(jid,cid);history(req,'pink_pack_purchase',id,'Third-party acquisition cost',{}, {cost_id:cid,supplier_id:s.id,journal_id:jid,amount,currency,treatment,reason:b.reason});return {id,cost_id:cid,journal_id:jid}}
 route('post','/purchases/:id/external-costs',['finance'],req=>idempotent(req,()=>{permission(req,'finance');return authorize(req,'External cost',Number(req.params.id),req.body,()=>externalCost(req,Number(req.params.id),req.body),'pink_salt.packaging_correction')}));

 function reverseExternalCost(req,id,b){permission(req,'finance');reasonRequired(b);const bu=guard(req),c=db.prepare("SELECT * FROM pink_pack_external_costs WHERE id=? AND business_unit_id=? AND status='Active'").get(id,bu);if(!c)fail('Active external cost not found.',404);if(sum("SELECT COUNT(*) v FROM pink_fx_transactions WHERE workflow='packaging_cost' AND record_id=? AND status='Active'",id))fail('Reverse the external-cost payments before correcting this invoice.',409);const p=purchase(c.purchase_id,bu),d=date(b.effective_date);openPeriod(bu,d);let variance=0;for(const a of json(c.allocation_json)){const m=material(a.material_id,bu),qty=balance(m.id),remove=Math.min(round(qty*m.last_unit_cost_krw),D.proportionMoney(a.inventory_value,Math.min(qty,a.stock_quantity),a.stock_quantity));variance=D.total([variance,a.inventory_value,-remove]);if(qty>0)db.prepare('UPDATE pink_salt_packaging_items SET last_unit_cost_krw=? WHERE id=?').run(Math.max(0,qty*m.last_unit_cost_krw-remove)/qty,m.id);move(req,{packaging_item_id:m.id,movement_date:d,movement_type:'Acquisition Cost Reversal',quantity:0,unit_cost_krw:qty?remove/qty:0,reference_type:'Packaging External Cost Reversal',reference_id:id,reference:c.invoice_reference,purchase_id:p.id,notes:b.reason})}const reversal=accounting.reverseJournal(db.prepare('SELECT * FROM accounting_journal_entries WHERE id=?').get(c.journal_id),b.reason,req.user.id);let varianceJournal=null;if(variance)varianceJournal=journal(req,p,'Pink Packaging Cost Reversal Variance',id,d,[jl('PINK_SALT_PACKAGING_INVENTORY',variance,0),jl('GENERAL_EXPENSE',0,variance)]);db.prepare("UPDATE pink_pack_external_costs SET status='Reversed' WHERE id=?").run(id);history(req,'pink_pack_purchase',p.id,'External cost reversed',c,{reversal_journal_id:reversal,variance_journal_id:varianceJournal,reason:b.reason});return {id:p.id,cost_id:id,reversal_journal_id:reversal,variance_journal_id:varianceJournal}}
 route('post','/external-costs/:id/reverse',['finance'],req=>idempotent(req,()=>{permission(req,'finance');req.body={...req.body,cost_id:Number(req.params.id)};return authorize(req,'External cost reversal',null,req.body,()=>reverseExternalCost(req,Number(req.params.id),req.body),'pink_salt.packaging_correction')}));

 function reverseCredit(req,id,b){permission(req,'finance');reasonRequired(b);const bu=guard(req),c=db.prepare("SELECT * FROM pink_pack_credits WHERE id=? AND business_unit_id=? AND status='Active'").get(id,bu);if(!c)fail('Active supplier credit note not found.',404);const p=purchase(c.purchase_id,bu),f=financial(p);if(f.refunded_krw>.005)fail('Reverse supplier refunds before reversing the credit note.',409);const d=date(b.effective_date);openPeriod(bu,d);openPeriod(bu,now());const j=db.prepare('SELECT * FROM accounting_journal_entries WHERE id=?').get(c.journal_id),rid=accounting.reverseJournal(j,b.reason,req.user.id);db.prepare("UPDATE pink_pack_credits SET status='Reversed',reversed_at=CURRENT_TIMESTAMP WHERE id=?").run(id);const rl=db.prepare('SELECT purchase_line_id FROM pink_pack_receipt_lines WHERE id=?').get(c.receipt_line_id);db.prepare('UPDATE pink_pack_purchase_lines SET cancelled_quantity=MAX(0,cancelled_quantity-?) WHERE id=?').run(c.quantity,rl.purchase_line_id);db.prepare("UPDATE pink_pack_purchases SET revision=revision+1,status='Approved' WHERE id=?").run(p.id);history(req,'pink_pack_purchase',p.id,'Supplier credit reversed',c,{reason:b.reason,reversal_journal_id:rid});return {id:p.id,credit_id:id,reversal_journal_id:rid}}
 route('post','/credits/:id/reverse',['finance'],req=>idempotent(req,()=>{permission(req,'finance');req.body={...req.body,credit_id:Number(req.params.id)};return authorize(req,'Supplier credit reversal',null,req.body,()=>reverseCredit(req,Number(req.params.id),req.body),'pink_salt.packaging_correction')}));

 // Controlled extensions reuse the existing approval executor and Posting Control.
 function reasonRequired(b){if(!text(b.reason))fail('A reason is required.');return text(b.reason)}
 function signed(key,value,meta={}){return jl(key,Math.max(0,value),Math.max(0,-value),meta)}
