 function requirements(req,outputs){const bu=guard(req),needed=new Map(),snapshot=[];if(!Array.isArray(outputs)||!outputs.length)fail('Select production outputs.');for(const o of outputs){const p=db.prepare('SELECT * FROM pink_salt_products WHERE id=? AND business_unit_id=? AND active=1').get(Number(o.product_id),bu),q=D.number(D.fixed(o.quantity_units));if(!p||!(q>0)||!Number.isInteger(q))fail('Select valid production products and quantities.');const bom=db.prepare('SELECT * FROM pink_salt_bom_lines WHERE product_id=? ORDER BY id').all(p.id);snapshot.push({product_id:p.id,quantity_units:q,bom});for(const l of bom)needed.set(l.packaging_item_id,D.total([needed.get(l.packaging_item_id)||0,D.multiply(l.quantity_per_unit,q)]))}return {needed,snapshot}}
 function reserve(req,b){permission(req,'inventory');reasonRequired(b);const bu=guard(req),outputs=json(b.outputs),{needed,snapshot}=requirements(req,outputs),loc=location(req,b.location_id);if(!text(b.reference)||!needed.size)fail('Reference and packaging requirements are required.');for(const [id,q] of needed)if(available(id,loc.id)<q-0.000001)fail('Insufficient unreserved material stock.',409);const id=insert('pink_pack_reservations',{business_unit_id:bu,reference:text(b.reference),outputs_json:JSON.stringify(outputs),bom_json:JSON.stringify(snapshot),reason:b.reason,created_by:req.user.id});for(const [material_id,quantity] of needed)insert('pink_pack_reservation_lines',{reservation_id:id,material_id,location_id:loc.id,quantity});history(req,'pink_pack_reservation',id,'Reserved',{}, {outputs,lines:[...needed]});return {id}}
